\caption{Increasing overlap using an auxiliary edge $\{v',w'\}\in\eta\cap\eta'$. Only the relevant edges are drawn, in the case of seven distinct named vertices; all other edges remain unchanged. The gray regions depict the fixed forbidden set $B$, defined using the original $\sigma\cup\eta\cup\eta'$, with unnamed neighbors omitted. Both auxiliary endpoints lie outside $B$. The final completions lose the common edge $\{v',w'\}$ and gain the common edges $\{v,w\}$ and $\{u,v'\}$, so $|\eta''\cap\eta'''|\ge |\eta\cap\eta'|+1$.}
\label{fig:auxiliary-edge}
\end{figure}
 use an auxiliary edge to increase the overlap, allowing both completions to move within their components. Let $B$ consist of $u,v,w,z,u'$ and all their neighbors in $\sigma\cup\eta\cup\eta'$. Both $\sigma\cup\eta$ and $\sigma\cup\eta'$ have maximum degree at most $\Delta$, so each vertex has at most $2\Delta$ neighbors in their union. Each of the five specified vertices therefore contributes at most $2\Delta+1$ vertices to $B$, giving
        \begin{align*}
            |B| &\le5(2\Delta+1).
        \end{align*}
    Every edge of $\eta$ meeting $B$ is counted at least once in $\sum_{z'\in B}\mathrm{deg}_{\eta}(z')$, and $\mathrm{deg}_{\eta}(z')\le\Delta$. Consequently,
        \begin{align*}
            |\{\{u'',v''\}\in\eta:\{u'',v''\}\cap B\ne\varnothing\}| &\le\sum_{z'\in B}\mathrm{deg}_{\eta}(z')\\
            &\le\Delta|B|\le5\Delta(2\Delta+1)\\
            &\le15\Delta^{2}<k.
        \end{align*}
    Choose $\{v',w'\}\in\eta$ with $\{v',w'\}\cap B=\varnothing$. In particular,
        \begin{align*}
            \{\{u,v'\},\{v,w'\},\{z,w'\},\{u',w'\}\}\cap(\sigma\cup\eta\cup\eta') &= \varnothing.
        \end{align*}
    In $\eta$, perform the following two steps of $\mathbf{P}_2^{(\sigma)}$:
        \begin{align*}
            \{\{u,v\},\{w,z\},\{v',w'\}\} &\mapsto\{\{u,v'\},\{w,z\},\{v,w'\}\}\mapsto\{\{u,v'\},\{v,w\},\{z,w'\}\},
        \end{align*}
    obtaining $\eta''$ in the same component as $\eta$. The endpoint exclusions above and the choice of $\{v',w'\}$ ensure that both switches are valid. If $\{v',w'\}\notin\eta'$, these switches remove no common edges and add the common edge $\{v,w\}$, giving
        \begin{align*}
            |\eta''\cap\eta'| &= |\eta\cap\eta'|+1,
        \end{align*}
    contrary to maximality. Thus $\{v',w'\}\in\eta'$. Now perform one switch in $\eta'$:
        \begin{align*}
            \{\{u,u'\},\{v',w'\}\} &\mapsto\{\{u,v'\},\{u',w'\}\},
        \end{align*}
    obtaining $\eta'''$ in the same component as $\eta'$. This switch is valid by the choice of $\{v',w'\}$. Every original common edge except $\{v',w'\}$ remains common, while $\{v,w\}$ and $\{u,v'\}$ are now both common. Therefore
        \begin{align*}
            |\eta''\cap\eta'''| &\ge|\eta\cap\eta'|-1+2>|\eta\cap\eta'|.
        \end{align*}
    Since $\eta''$ and $\eta'''$ remain in different components, this contradicts maximality and proves the claim.

    The preceding argument proves something stronger and useful. Starting from any two completions, repeat the construction until they coincide. Each application uses two valid steps from the first completion and at most one from the second, increasing their overlap by at least one. Since both completions have $k$ edges, at most $k$ applications are needed. Following the switches from the first completion and then reversing those from the second gives a walk of length at most $3k$ between them.

    We now prove~\cref{eq:finite-local-variance} using the crude bound on $|\mathcal{R}_{\mathbf{d}}^{(\sigma)}(k)|$ and the preceding path bound. If $|\mathcal{R}_{\mathbf{d}}^{(\sigma)}(k)|=1$, the variance is zero. Otherwise, choose a simple path $\eta_{0},\dotsc,\eta_{\ell}$ from a minimum of $g$ to a maximum, with $\ell\le3k$. Telescoping and Cauchy--Schwarz give
        \begin{align*}
            \operatorname{Var}_{\eta\sim\pi_{k}^{\sigma}}(g(\eta)) &\le(g(\eta_{\ell})-g(\eta_{0}))^{2}\\
            &= \Bigl(\sum_{i=0}^{\ell-1}(g(\eta_{i+1})-g(\eta_{i}))\Bigr)^{2}\\
            &\le\ell\sum_{i=0}^{\ell-1}(g(\eta_{i+1})-g(\eta_{i}))^{2}.
        \end{align*}
    By the preceding and the fact that $\mathbf{P}_{2}^{(\sigma)}$ is reversible with respect to the uniform measure on $\mathcal{R}_{\mathbf{d}}^{(\sigma)}(k)$, it follows that
        \begin{align*}
            \mathcal{E}_{\mathbf{P}_{2}^{(\sigma)}}(g,g) &= \frac{1}{2|\mathcal{R}_{\mathbf{d}}^{(\sigma)}(k)|}\sum_{\eta,\eta'\in\mathcal{R}_{\mathbf{d}}^{(\sigma)}(k)}\mathbf{P}_{2}^{(\sigma)}(\eta,\eta')(g(\eta')-g(\eta))^{2}\\
            &\ge\frac{1}{|\mathcal{R}_{\mathbf{d}}^{(\sigma)}(k)|}\sum_{i=0}^{\ell-1}\mathbf{P}_{2}^{(\sigma)}(\eta_{i},\eta_{i+1})(g(\eta_{i+1})-g(\eta_{i}))^{2}\\
            &\ge\frac{1}{3\binom{k}{2}|\mathcal{R}_{\mathbf{d}}^{(\sigma)}(k)|}\sum_{i=0}^{\ell-1}(g(\eta_{i+1})-g(\eta_{i}))^{2}.
        \end{align*}
    In the last line, we use the basic bound
        \begin{align*}
            \mathbf{P}_{2}^{(\sigma)}(\eta_{i},\eta_{i+1}) &\ge\frac{1}{3\binom{k}{2}},
        \end{align*}
    since the walk chooses one of $\binom{k}{2}$ edge pairs and then one of at most three completions. Combining these inequalities,
        \begin{align*}
            \operatorname{Var}_{\eta\sim\pi_{k}^{\sigma}}(g(\eta)) &\le3\binom{k}{2}|\mathcal{R}_{\mathbf{d}}^{(\sigma)}(k)|\ell\,\mathcal{E}_{\mathbf{P}_{2}^{(\sigma)}}(g,g)\\
            &\le9k\binom{k}{2}(2k-1)!!\,\mathcal{E}_{\mathbf{P}_{2}^{(\sigma)}}(g,g).
        \end{align*}
    This proves~\cref{eq:finite-local-variance}.

    Finally, for each $\rho\in\mathcal{R}_{\mathbf{d}}^{(\sigma)}(k-j)$ and $\eta\in\mathcal{R}_{\mathbf{d}}^{(\sigma\cup\rho)}(j)$, write $g^{(\rho)}(\eta)=g(\rho\cup\eta)$. Applying~\cref{eq:finite-local-variance} with $k$ replaced by $j$ and retained face $\sigma\cup\rho$, and using~\cref{lem:dirichlet-energy-decomposition}(ii), we obtain
        \begin{align*}
            &\mathcal{E}_{\mathbf{P}_{j}^{(\sigma)}}(g,g)\\
            &\quad= \mathbb{E}_{\rho\sim\pi_{k-j}^{\sigma}}\Bigl(\operatorname{Var}_{\eta\sim\pi_{j}^{\sigma\cup\rho}}(g^{(\rho)}(\eta))\Bigr)\\
            &\quad\le C_{j}\mathbb{E}_{\rho\sim\pi_{k-j}^{\sigma}}\Bigl(\mathcal{E}_{\mathbf{P}_{2}^{(\sigma\cup\rho)}}(g^{(\rho)},g^{(\rho)})\Bigr)\\
            &\quad= C_{j}\mathcal{E}_{\mathbf{P}_{2}^{(\sigma)}}(g,g).
        \end{align*}
    This proves~\cref{eq:finite-comparison}.

\label{lem:good-restriction-probability}
    Let $k,\ell$ be integers satisfying $k\le m$ and $10^{6}\Delta^{4}\le\ell\le\sqrt{k}$, and let $\sigma\in\mathcal{R}_{\mathbf{d}}(m-k)$. Let $\mathcal{A}\subseteq\mathcal{R}_{\mathbf{d}}^{(\sigma)}(k-\ell)$ consist of those partial completions $\rho$ such that
        \begin{align*}
            \mathrm{res}_{\sigma\cup\rho}(v)+\mathrm{deg}_{\widetilde{\sigma\cup\rho}}(v) &\le10
        \end{align*}
    for each $v\in V_{\sigma\cup\rho}$. For each completion $\eta\in\mathcal{R}_{\mathbf{d}}^{(\sigma)}(k)$, let $\mu_{\eta}$ be the uniform probability measure on the $(k-\ell)$-edge subsets of $\eta$. Then
        \begin{align}\label{eq:bad-probability}
            \mathbb{P}_{\rho\sim\mu_{\eta}}(\rho\notin\mathcal{A}) &\le\frac{\ell}{4k}.
        \end{align}

Fix $\eta\in\mathcal{R}_{\mathbf{d}}^{(\sigma)}(k)$, so that only $\rho\sim\mu_{\eta}$ is random. For every such $\rho$,
        \begin{align*}
            \mathrm{res}_{\sigma\cup\rho}(v) &= \mathrm{res}_{\sigma}(v)-\mathrm{deg}_{\rho}(v)=\mathrm{deg}_{\eta\setminus\rho}(v),\qquad v\in V.
        \end{align*}
    Thus $V_{\sigma\cup\rho}$ consists exactly of the endpoints of the $\ell$ edges in $\eta\setminus\rho$. For each $v\in V_{\sigma\cup\rho}$, the modified residual degree is therefore
        \begin{align*}
            \mathrm{res}_{\sigma\cup\rho}(v)+\mathrm{deg}_{\widetilde{\sigma\cup\rho}}(v) &= \mathrm{deg}_{\eta\setminus\rho}(v)+\mathrm{deg}_{\widetilde{\sigma\cup\rho}}(v)\\
            &= \mathrm{deg}_{(\sigma\cup\eta)[V_{\sigma\cup\rho}]}(v).
        \end{align*}
    Consequently, if $\rho\notin\mathcal{A}$, there exists some $v\in V_{\sigma\cup\rho}$ with at least $11$ active neighbors in the fixed realization $\sigma\cup\eta$.

    For each $v\in V_{\sigma}$, let $B_{v}$ be the closed neighborhood of $v$ in $\sigma\cup\eta$. Then $|B_{v}|\le\Delta+1$. If $\rho\notin\mathcal{A}$, there is some $v\in V_{\sigma\cup\rho}\subseteq V_{\sigma}$ for which
        \begin{align*}
            |B_{v}\cap V_{\sigma\cup\rho}| &\ge12.
        \end{align*}
    Each of these vertices is incident to an edge of $\eta\setminus\rho$, and one edge accounts for at most two vertices. Thus at least six distinct edges of $\eta\setminus\rho$ meet $B_{v}$. These edges need not be vertex-disjoint. The degree cutoff $10$ is what forces these six distinct edges.

    For a fixed center $v$, the number of edges of $\eta$ meeting $B_{v}$ is at most
        \begin{align*}
            |\{\{u,w\}\in\eta:\{u,w\}\cap B_{v}\ne\varnothing\}| &\le\sum_{u\in B_{v}}\mathrm{deg}_{\eta}(u) \le\Delta(\Delta+1) \le2\Delta^{2}.
        \end{align*}
    The set $\eta\setminus\rho$ is uniform among the $\ell$-edge subsets of $\eta$. Hence, for any fixed $\tau\subseteq\eta$ with $|\tau|=6$,
        \begin{align*}
            \mathbb{P}_{\rho\sim\mu_{\eta}}(\tau\subseteq\eta\setminus\rho) &= \frac{\binom{k-6}{\ell-6}}{\binom{k}{\ell}} = \frac{\ell}{k}\frac{\ell-1}{k-1}\cdots\frac{\ell-5}{k-5} \le\Bigl(\frac{\ell}{k}\Bigr)^{6}.
        \end{align*}
    The set $V_{\sigma}$ consists of the endpoints of the $k$ edges of $\eta$, so there are at most $2k$ possible centers. Taking a union bound over these centers and their six-edge subsets, and using $k\ge\ell^{2}$, gives
        \begin{align*}
            \mathbb{P}_{\rho\sim\mu_{\eta}}(\rho\notin\mathcal{A}) &\le2k\binom{2\Delta^{2}}{6}\Bigl(\frac{\ell}{k}\Bigr)^{6} \le\frac{128\Delta^{12}\ell^{6}}{k^{5}} \le\frac{128\Delta^{12}}{\ell^{3}}\frac{\ell}{k} \le\frac{128}{10^{18}}\frac{\ell}{k} \le\frac{\ell}{4k}.
        \end{align*}
    Here $\binom{a}{6}=0$ when $a<6$, and the penultimate inequality uses $\ell\ge10^{6}\Delta^{4}$. The completion $\eta$ was arbitrary, so~\cref{eq:bad-probability} holds for every starting completion.

\label{prop:linear-comparison}
    There exist absolute constants $C,C'>0$ with the following property. Let $k$ be an integer satisfying $C\Delta^{8}\le k\le m$. Then, for every $f\in\ell^{2}(\mathcal{R}_{\mathbf{d}}(m),\pi_{m})$,
        \begin{align}\label{eq:linear-comparison}
            \mathcal{E}_{\mathbf{P}_{k}}(f,f) &\le C'k\,\mathcal{E}_{\mathbf{P}_{2}}(f,f).
        \end{align}

Set $C=k_{0}^{2}$, and let $f\in\ell^{2}(\mathcal{R}_{\mathbf{d}}(m),\pi_{m})$. For each $\sigma\in\mathcal{R}_{\mathbf{d}}(m-k)$, write $f^{(\sigma)}(\eta)=f(\sigma\cup\eta)$ for $\eta\in\mathcal{R}_{\mathbf{d}}^{(\sigma)}(k)$. We first decompose the energy according to the retained $(m-k)$-face. By~\cref{lem:dirichlet-energy-decomposition}(ii), applied with the empty retained face, we have
        \begin{align*}
            \mathcal{E}_{\mathbf{P}_{k}}(f,f) &= \mathbb{E}_{\sigma\sim\pi_{m-k}}\Bigl(\operatorname{Var}_{\eta\sim\pi_{k}^{\sigma}}(f^{(\sigma)}(\eta))\Bigr).
        \end{align*}
    We will bound each variance term appearing inside the mean above by the corresponding Dirichlet energy with respect to ${\mathbf{P}_{2}^{(\sigma)}}$. These local energies average to the two-edge energy on the full complex: by~\cref{lem:dirichlet-energy-decomposition}(iii),
        \begin{align*}
            \mathbb{E}_{\sigma\sim\pi_{m-k}}\Bigl(\mathcal{E}_{\mathbf{P}_{2}^{(\sigma)}}(f^{(\sigma)},f^{(\sigma)})\Bigr) &= \mathcal{E}_{\mathbf{P}_{2}}(f,f).
        \end{align*}
    Thus it suffices to prove a uniform variance bound within each link. Fix $\sigma\in\mathcal{R}_{\mathbf{d}}(m-k)$ and $g\in\ell^{2}(\mathcal{R}_{\mathbf{d}}^{(\sigma)}(k),\pi_{k}^{\sigma})$. We will show that
        \begin{align}\label{eq:target-local-poincare}
            \operatorname{Var}_{\eta\sim\pi_{k}^{\sigma}}(g(\eta)) &\le4C_{10}k\,\mathcal{E}_{\mathbf{P}_{2}^{(\sigma)}}(g,g).
        \end{align}
    Subtracting the mean of $g$ changes neither its variance nor its Dirichlet energies, so we may assume freely that $\mathbb{E}_{\eta\sim\pi_{k}^{\sigma}}(g(\eta))= 0$. Let $\ell=k_{0}\Delta^{4}$ be the number of edges left free after the additional restriction. Our assumptions give
        \begin{align}\label{eq:restriction-parameters}
            10^{6}\Delta^{4} &\le\ell\le\sqrt{k},
        \end{align}
    so~\cref{lem:higher-order-poincare} yields
        \begin{align}\label{eq:restriction-poincare}
            \operatorname{Var}_{\eta\sim\pi_{k}^{\sigma}}(g(\eta)) &\le\frac{2k}{\ell}\mathcal{E}_{\mathbf{P}_{\ell}^{(\sigma)}}(g,g).
        \end{align}
    For each $\rho\in\mathcal{R}_{\mathbf{d}}^{(\sigma)}(k-\ell)$, write $g^{(\rho)}(\eta')=g(\rho\cup\eta')$ for $\eta'\in\mathcal{R}_{\mathbf{d}}^{(\sigma\cup\rho)}(\ell)$. Let $\mathcal{A}$ be the set in~\cref{lem:good-restriction-probability}, consisting of those faces $\rho$ for which the modified residual degrees satisfy
        \begin{align}\label{eq:good-restrictions}
            \mathrm{res}_{\sigma\cup\rho}(v)+\mathrm{deg}_{\widetilde{\sigma\cup\rho}}(v) &\le10,\qquad v\in V_{\sigma\cup\rho}.
        \end{align}
    This condition depends only on the retained face $\sigma\cup\rho$. By~\cref{lem:dirichlet-energy-decomposition}(iii), we can split the energy according to whether this condition holds:
        \begin{align}\label{eq:restriction-energy-split}
            \mathcal{E}_{\mathbf{P}_{\ell}^{(\sigma)}}(g,g) &= \mathbb{E}_{\rho\sim\pi_{k-\ell}^{\sigma}}\Bigl(\mathbf{1}_{\rho\in\mathcal{A}}\operatorname{Var}_{\eta'\sim\pi_{\ell}^{\sigma\cup\rho}}(g^{(\rho)}(\eta'))\Bigr)\notag\\
            &\qquad+\mathbb{E}_{\rho\sim\pi_{k-\ell}^{\sigma}}\Bigl(\mathbf{1}_{\rho\notin\mathcal{A}}\operatorname{Var}_{\eta'\sim\pi_{\ell}^{\sigma\cup\rho}}(g^{(\rho)}(\eta'))\Bigr).
        \end{align}

    We first bound the contribution from the good set $\mathcal{A}$. For each $\rho\in\mathcal{A}$,~\cref{eq:identical-links} and the surrounding discussion identify $\mathcal{R}_{\mathbf{d}}^{(\sigma\cup\rho)}$ with a link of a switch complex whose prescribed degrees are positive and at most $10$. This identification preserves the uniform facet measure and the down-up walks, and the facets still have size $\ell$. Since $\ell\ge k_{0}$, it follows that
        \begin{align*}
            \operatorname{Var}_{\eta'\sim\pi_{\ell}^{\sigma\cup\rho}}(g^{(\rho)}(\eta')) &\le C_{10}\ell\,\mathcal{E}_{\mathbf{P}_{2}^{(\sigma\cup\rho)}}(g^{(\rho)},g^{(\rho)}).
        \end{align*}
    Averaging over $\rho\in\mathcal{A}$, using nonnegativity of the energies, and applying~\cref{lem:dirichlet-energy-decomposition}(iii), we obtain
        \begin{align}\label{eq:averaged-good-bound}
            &\mathbb{E}_{\rho\sim\pi_{k-\ell}^{\sigma}}\Bigl(\mathbf{1}_{\rho\in\mathcal{A}}\operatorname{Var}_{\eta'\sim\pi_{\ell}^{\sigma\cup\rho}}(g^{(\rho)}(\eta'))\Bigr)\notag\\
            &\quad\le C_{10}\ell\,\mathbb{E}_{\rho\sim\pi_{k-\ell}^{\sigma}}\Bigl(\mathbf{1}_{\rho\in\mathcal{A}}\mathcal{E}_{\mathbf{P}_{2}^{(\sigma\cup\rho)}}(g^{(\rho)},g^{(\rho)})\Bigr)\notag\\
            &\quad\le C_{10}\ell\,\mathcal{E}_{\mathbf{P}_{2}^{(\sigma)}}(g,g).
        \end{align}

    For the second term appearing on the right-hand side of~\cref{eq:restriction-energy-split}, we bound the variance by the second moment. For each completion $\eta\in\mathcal{R}_{\mathbf{d}}^{(\sigma)}(k)$, let $\mu_{\eta}$ be uniform on its $(k-\ell)$-edge subsets. Expanding the second moment and using~\cref{lem:dirichlet-energy-decomposition}(i), we have
        \begin{align}\label{eq:bad-second-moment}
            &\mathbb{E}_{\rho\sim\pi_{k-\ell}^{\sigma}}\Bigl(\mathbf{1}_{\rho\notin\mathcal{A}}\operatorname{Var}_{\eta'\sim\pi_{\ell}^{\sigma\cup\rho}}(g^{(\rho)}(\eta'))\Bigr)\notag\\
            &\quad\le\sum_{\rho\in\mathcal{R}_{\mathbf{d}}^{(\sigma)}(k-\ell)}\Bigl(\pi_{k-\ell}^{\sigma}(\rho)\mathbf{1}_{\rho\notin\mathcal{A}}\sum_{\eta'\in\mathcal{R}_{\mathbf{d}}^{(\sigma\cup\rho)}(\ell)}\pi_{\ell}^{\sigma\cup\rho}(\eta')g^{(\rho)}(\eta')^{2}\Bigr)\notag\\
            &\quad=\sum_{\eta\in\mathcal{R}_{\mathbf{d}}^{(\sigma)}(k)}\Bigl(\pi_{k}^{\sigma}(\eta)g(\eta)^{2} \sum_{\substack{\rho\subseteq\eta\\|\rho|=k-\ell}}\frac{\mathbf{1}_{\rho\notin\mathcal{A}}}{\binom{k}{k-\ell}}\Bigr)\notag\\
            &\quad=\mathbb{E}_{\eta\sim\pi_{k}^{\sigma}}\Bigl(g(\eta)^{2}\mathbb{P}_{\rho\sim\mu_{\eta}}(\rho\notin\mathcal{A})\Bigr).
        \end{align}
    By~\cref{eq:restriction-parameters}, the hypotheses of~\cref{lem:good-restriction-probability} hold. Applying its probability bound inside the expectation in~\cref{eq:bad-second-moment} and using the fact that $g$ is centered, we obtain
        \begin{align}\label{eq:averaged-bad-bound}
            \mathbb{E}_{\rho\sim\pi_{k-\ell}^{\sigma}}\Bigl(\mathbf{1}_{\rho\notin\mathcal{A}}\operatorname{Var}_{\eta'\sim\pi_{\ell}^{\sigma\cup\rho}}(g^{(\rho)}(\eta'))\Bigr) & \le\frac{\ell}{4k}\mathbb{E}_{\eta\sim\pi_{k}^{\sigma}}(g(\eta)^{2}) = \frac{\ell}{4k}\operatorname{Var}_{\eta\sim\pi_{k}^{\sigma}}(g(\eta)).
        \end{align}

    Combining~\cref{eq:restriction-poincare,eq:restriction-energy-split,eq:averaged-good-bound,eq:averaged-bad-bound}, we obtain
        \begin{align*}
            \operatorname{Var}_{\eta\sim\pi_{k}^{\sigma}}(g(\eta)) &\le\frac{2k}{\ell}\mathcal{E}_{\mathbf{P}_{\ell}^{(\sigma)}}(g,g) \le2C_{10}k\,\mathcal{E}_{\mathbf{P}_{2}^{(\sigma)}}(g,g)+\frac{1}{2}\operatorname{Var}_{\eta\sim\pi_{k}^{\sigma}}(g(\eta)).
        \end{align*}
    Subtracting the last term and multiplying by $2$ proves~\cref{eq:target-local-poincare}. 

    Finally, applying~\cref{eq:target-local-poincare} with $g=f^{(\sigma)}$ for each $\sigma$ and using the two energy decompositions from the start of the proof, we obtain
        \begin{align*}
            \mathcal{E}_{\mathbf{P}_{k}}(f,f) &= \mathbb{E}_{\sigma\sim\pi_{m-k}}\Bigl(\operatorname{Var}_{\eta\sim\pi_{k}^{\sigma}}(f^{(\sigma)}(\eta))\Bigr)\\
            &\le4C_{10}k\,\mathbb{E}_{\sigma\sim\pi_{m-k}}\Bigl(\mathcal{E}_{\mathbf{P}_{2}^{(\sigma)}}(f^{(\sigma)},f^{(\sigma)})\Bigr)\\
            &=4C_{10}k\,\mathcal{E}_{\mathbf{P}_{2}}(f,f).
        \end{align*}
    Thus $C=k_{0}^{2}$ and $C'=4C_{10}$ satisfy~\cref{eq:linear-comparison}. The proposition is proved.

We first bound $\lambda_{2}(\mathbf{P}_{2})$ from above. Taking $C \ge 6$ sufficiently large, we may apply~\cref{prop:linear-comparison} with $k=m$ to obtain
        \begin{align*}
            \mathcal{E}_{\mathbf{P}_{2}}(f,f) &\ge\frac{1}{Cm}\mathcal{E}_{\mathbf{P}_{m}}(f,f)=\frac{1}{Cm}\operatorname{Var}_{\eta\sim\pi_{m}}(f(\eta))
        \end{align*}
    for every $f\in\ell^{2}(\mathcal{R}_{\mathbf{d}}(m),\pi_{m})$. Here the equality follows because $\mathbf{P}_{m}$ resamples the entire realization. By the variational characterization of the spectral gap, this gives the desired upper bound on $\lambda_{2}(\mathbf{P}_{2})$.

    For the reverse bound, fix $\{u,v\}\in\mathcal{R}_{\mathbf{d}}(1)$ and write $p=\mathbb{P}_{\eta\sim\pi_{m}}(\{u,v\}\in\eta)$. By \cref{lem:uniform-projection-lift}\emph{(i)} and~\cref{lem:single-pair-marginals}, applied with $\sigma=\varnothing$ and $k=m$, summing over the $d_{u}d_{v}$ stub pairs projecting to $\{u,v\}$ gives
        \begin{align*}
            0<p &\le\frac{d_{u}d_{v}}{2m-2-4\Delta^{2}}\le\frac{\Delta^{2}}{2m-2-4\Delta^{2}}\le\frac{1}{3},
        \end{align*}
    where the last inequality uses $m\ge6\Delta^{2}$. Define $g(\eta)=\mathbf{1}_{\{\{u,v\}\in\eta\}}$, so that $\operatorname{Var}_{\eta\sim\pi_{m}}(g(\eta))=p(1-p)$.

    An edge present in the current realization can disappear only if it is among the two deleted edges, which occurs with probability $2/m$. After deletion there are at most three valid completions, including the original pair, so the conditional probability of losing $\{u,v\}$ is at most $2/3$. By reversibility,
        \begin{align*}
            \mathcal{E}_{\mathbf{P}_{2}}(g,g) &=\sum_{\substack{\eta\in\mathcal{R}_{\mathbf{d}}(m)\\\{u,v\}\in\eta}}\pi_{m}(\eta)\sum_{\substack{\tau\in\mathcal{R}_{\mathbf{d}}(m)\\\{u,v\}\notin\tau}}\mathbf{P}_{2}(\eta,\tau) \le p\frac{2}{m}\frac{2}{3}=\frac{4p}{3m}.
        \end{align*}
    Applying the variational characterization once more, we obtain
        \begin{align*}
            1-\lambda_{2}(\mathbf{P}_{2}) &\le\frac{\mathcal{E}_{\mathbf{P}_{2}}(g,g)}{\operatorname{Var}_{\eta\sim\pi_{m}}(g(\eta))}\le\frac{4}{3m(1-p)}\le\frac{2}{m}.
        \end{align*}
    This proves the remaining bound.

\label{thm:two-edge-mixing}
    There exists an absolute constant $C>0$ with the following property. If $m\ge C\Delta^{8}$, then
        \begin{align*}
            t_{\mathrm{mix}}(\mathbf{P}_{2},1/4) &\le C\Delta^{2}m\log(m).
        \end{align*}

\label{lem:salez-entropy-gap}
    Let $\mathbf{Q}$ be a Markov kernel on a finite set $\mathcal{Y}$ with at least two elements and stationary measure $\pi$. Let $r\ge0$ be an integer and let $K\ge0$. Suppose that $\mathbf{Q}$ is irreducible, reversible, positive semidefinite, and that
        \begin{align*}
            D(\mathbf{Q}^{r}(x,\cdot)\,\Vert\,\pi) &\le K
        \end{align*}
    for every $x\in\mathcal{Y}$. Then
        \begin{align*}
            t_{\mathrm{mix}}(\mathbf{Q},1/4) &\le r+ \frac{4(K+1)}{1-\lambda_{2}(\mathbf{Q})}.
        \end{align*}

If $K=0$, then $\mathbf{Q}^{r}(x,\cdot)=\pi$ for every $x$, and the conclusion follows, so we assume $K>0$. Fix $x\in\mathcal{Y}$ and write $\mu(y)=\mathbf{Q}^{r}(x,y)/\pi(y)$. Set $A=\{y\in\mathcal{Y}:\mu(y)< e^{1+8K}\}$. The function $u\mapsto u\log u - u + 1$ is nonnegative on $u\ge 0$ and satisfies $u\log u-u+1\ge 8Ku$ for each $u\ge e^{1+8K}$. Thus
        \begin{align*}
            8K\sum_{y\notin A}\pi(y)\mu(y) &\le\sum_{y\notin A}\pi(y)(\mu(y)\log \mu(y)-\mu(y)+1)\\
            &\le\sum_{y\in\mathcal{Y}}\pi(y)(\mu(y)\log \mu(y)-\mu(y)+1)\\
            &=D(\mathbf{Q}^{r}(x,\cdot)\,\Vert\,\pi)\le K.
        \end{align*}
    Consequently $a=\sum_{y\in A}\pi(y)\mu(y)\ge7/8$. Define $\nu(y)=\mu(y)\mathbf{1}_{\{y\in A\}}/a$. Then $\mathbb{E}_{y\sim\pi}(\nu(y))=1$, and
        \begin{align*}
            \frac{1}{2}\sum_{y\in\mathcal{Y}}\pi(y)|\mu(y)-\nu(y)| &=\frac{1}{2}(a(\frac{1}{a}-1)+1-a)=1-a\le\frac{1}{8}.
        \end{align*}
    Additionally, we have
        \begin{align*}
            \operatorname{Var}_{y\sim\pi}(\nu(y)) &\le\sum_{y\in\mathcal{Y}}\pi(y)\nu(y)^{2}\le \frac{e^{1+8K}}{a} \sum_{y\in\mathcal{Y}}\pi(y)\nu(y)\le\frac{8}{7}e^{1+8K}\le e^{2+8K}.
        \end{align*}
    For each integer $s\ge1$, the triangle inequality and stationarity of $\pi$ give
        \begin{align}\label{eq:triangle-inequality-h-h0}
            \sum_{y\in\mathcal{Y}}\pi(y)|\mathbf{Q}^{s}(\mu-\nu)(y)| &\le\sum_{y,z\in\mathcal{Y}}\pi(y)\mathbf{Q}^{s}(y,z)|\mu(z)-\nu(z)|\notag\\
            &=\sum_{z\in\mathcal{Y}}\pi(z)|\mu(z)-\nu(z)|\le\frac{1}{4}.
        \end{align}
    By reversibility,
        \begin{align*}
            \pi(y)(\mathbf{Q}^{s}\mu)(y) &=\sum_{z\in\mathcal{Y}}\pi(z)\mathbf{Q}^{s}(z,y)\mu(z)=\mathbf{Q}^{r+s}(x,y),
        \end{align*}
    and therefore
        \begin{align*}
            \|\mathbf{Q}^{r+s}(x,\cdot)-\pi\|_{\mathrm{TV}} &=\frac{1}{2}\sum_{y\in\mathcal{Y}} \pi(y) |(\mathbf{Q}^{s} \mu)(y) - 1|\\
            &\le \frac{1}{2}\mathbb{E}_{y\sim\pi}(|(\mathbf{Q}^{s}\mu)(y) - (\mathbf{Q}^{s}\nu)(y)|) + \frac{1}{2}\mathbb{E}_{y\sim\pi}(|(\mathbf{Q}^{s}\nu)(y) - 1|)\\
            &\le \frac{1}{8} + \frac{1}{2}\Bigl(\sum_{y\in\mathcal{Y}}\pi(y) |(\mathbf{Q}^{s}\nu)(y) - 1|^{2} \Bigr)^{1/2},
        \end{align*}
    where the last inequality follows from~\cref{eq:triangle-inequality-h-h0} and the Cauchy--Schwarz inequality. By reversibility and positive semidefiniteness, $\mathbf{Q}$ has an $\ell^{2}(\mathcal{Y},\pi)$-orthonormal basis of eigenfunctions with eigenvalues in $[0,1]$. Since $\nu-\mathbf{1}$ is orthogonal to the first such eigenfunction with eigenvalue $\lambda_{1}(\mathbf{Q}) = 1$, it follows that
        \begin{align*}
            \sum_{y\in\mathcal{Y}}\pi(y) |(\mathbf{Q}^{s}\nu)(y) - 1|^{2} & \le \lambda_{2}(\mathbf{Q})^{2s}\|\nu-\mathbf{1}\|_{\pi}^{2} = \lambda_{2}(\mathbf{Q})^{2s}\operatorname{Var}_{y\sim\pi}(\nu(y)).
        \end{align*}
    Combining the preceding bounds, we obtain
        \begin{align*}
            \|\mathbf{Q}^{r+s}(x,\cdot)-\pi\|_{\mathrm{TV}} &\le \frac{1}{8} + \frac{1}{2}\lambda_{2}(\mathbf{Q})^{s}\sqrt{\operatorname{Var}_{y\sim\pi}(\nu(y))}\\
            &\le\frac{1}{8}+\frac{1}{2}\exp(1+4K-s(1-\lambda_{2}(\mathbf{Q}))).
        \end{align*}
    Taking $s=\lfloor4(K+1)/(1-\lambda_{2}(\mathbf{Q}))\rfloor$, we have $s(1-\lambda_{2}(\mathbf{Q}))\ge4(K+1)-(1-\lambda_{2}(\mathbf{Q}))\ge4K+3$, since $0<1-\lambda_{2}(\mathbf{Q})\le1$. The last expression is therefore at most $1/8+e^{-2}/2<1/4$, uniformly in $x$. Since $s\le4(K+1)/(1-\lambda_{2}(\mathbf{Q}))$, this proves the lemma.

\label{prop:two-edge-entropy-bound}
    Suppose that $m\ge2$, and let $r$ be an integer satisfying $r\ge3m\log(2m)$. Then
        \begin{align*}
            \max_{\sigma\in\mathcal{R}_{\mathbf{d}}(m)}D(\mathbf{P}_{2}^{r}(\sigma,\cdot)\,\Vert\,\pi_{m}) &\le193\Delta^{2}\log(2m).
        \end{align*}

\label{thm:random-transposition-l2}
    Let $N\ge2$, and let $\mathbf{Q}$ be the Markov kernel on the symmetric group $\mathfrak{S}_{N}$ on $N$ elements that at each step, from a permutation $\varphi$, moves to $\varphi\theta$, where $\theta$ is chosen uniformly among the $\binom{N}{2}$ transpositions. Let $\pi_{\mathfrak{S}}$ denote the uniform probability measure on $\mathfrak{S}_{N}$, and set $\mu_{t}=e^{t(\mathbf{Q}-\mathbf{I})}(\iota,\cdot)$ for each $t\ge0$, where $\iota$ is the identity permutation. Then, if $t\ge N\log N$, it holds
        \begin{align*}
            \Bigl\|\frac{\mu_{t}}{\pi_{\mathfrak{S}}}-\mathbf{1}\Bigr\|_{\pi_{\mathfrak{S}}}^{2} &\le1.
        \end{align*}

We use the pairing construction from~\cref{sec:deep-link-expansion} with $\sigma=\varnothing$ and $k=m$. As in that setting, write $\pi_{\mathcal{P}}$ and $\pi_{\mathcal{Q}}$ for the uniform probability measures on $\mathcal{P}$ and $\mathcal{Q}$, respectively. Fix $X\in\mathcal{Q}$.

    Define the kernel $\widehat{\mathbf{P}}$ on $\mathcal{Q}$ as follows. From $X\in\mathcal{Q}$, choose $W\in\binom{X}{2}$ uniformly and replace its two pairs by a uniformly chosen pairing of their four stubs for which the resulting pairing belongs to $\mathcal{Q}$. For each such $W$, let $\mathcal{M}(W)$ be the set of all three pairings of these four stubs, and write
        \begin{align*}
            g_{X}(W) &=|\{W'\in\mathcal{M}(W):(X\setminus W)\cup W'\in\mathcal{Q}\}|.
        \end{align*}
    Since $X$ was valid to begin with, $1\le g_{X}(W)\le3$. The two selected stub pairs correspond bijectively to two selected graph edges. If those edges are vertex-disjoint, valid stub completions correspond bijectively to graph completions, each with probability $1/g_{X}(W)$. If the selected pairs are $\{\vec{v},\vec{z}\},\{\vec{u},\vec{w}\}$ with $v=u$, the matching $\{\{\vec{u},\vec{z}\},\{\vec{v},\vec{w}\}\}$ gives the same graph as the original matching, while the third matching contains the pair $\{\vec{v},\vec{u}\}$, which projects to a loop. Thus $g_{X}(W)=2$, and the probability of restoring the graph is $1/2+1/2=1$. Averaging over the selected pairs gives, for every $\tau'\in\mathcal{R}_{\mathbf{d}}(m)$,
        \begin{align*}
            &\sum_{\substack{Y\in\mathcal{Q}\\\Phi(Y)=\tau'}}\widehat{\mathbf{P}}(X,Y)\\
            &\quad=\frac{1}{\binom{m}{2}}\sum_{W\in\binom{X}{2}}\frac{|\{W'\in\mathcal{M}(W):(X\setminus W)\cup W'\in\mathcal{Q},\ \Phi((X\setminus W)\cup W')=\tau'\}|}{g_{X}(W)}\\
            &\quad=\mathbf{P}_{2}(\Phi(X),\tau').
        \end{align*}
    The same projection identity holds for powers of the kernels, by induction. Let $s\ge 1$ be fixed. Then 
        \begin{align}\label{eq:pairing-projection-recursion}
            \sum_{\substack{Y\in\mathcal{Q}\\\Phi(Y)=\tau'}}\widehat{\mathbf{P}}^{\,s+1}(X,Y) &=\sum_{Z\in\mathcal{Q}}\widehat{\mathbf{P}}^{\,s}(X,Z)\mathbf{P}_{2}(\Phi(Z),\tau')\notag\\
            &=\sum_{\tau''\in\mathcal{R}_{\mathbf{d}}(m)}\mathbf{P}_{2}(\tau'',\tau') \sum_{\substack{Z\in\mathcal{Q} \\ \Phi(Z)=\tau''}}  \widehat{\mathbf{P}}^{\,s}(X,Z)\notag\\
            &=\sum_{\tau''\in\mathcal{R}_{\mathbf{d}}(m)}\mathbf{P}_{2}^{s}(\Phi(X),\tau'')\mathbf{P}_{2}(\tau'',\tau')\notag\\
            &=\mathbf{P}_{2}^{s+1}(\Phi(X),\tau'),
        \end{align}
    where in the second equality we group the terms according to $\tau''=\Phi(Z)$.

    Now let $r\ge 1$ be an integer. Using~\cref{lem:uniform-projection-lift}\emph{(i)} and the identity~\cref{eq:pairing-projection-recursion}, the log-sum inequality gives
        \begin{align*}
            &D(\mathbf{P}_{2}^{r}(\Phi(X),\cdot)\,\Vert\,\pi_{m})\\
            &\quad=\sum_{\tau'\in\mathcal{R}_{\mathbf{d}}(m)}\mathbf{P}_{2}^{r}(\Phi(X),\tau')\log\frac{\mathbf{P}_{2}^{r}(\Phi(X),\tau')}{\pi_{m}(\tau')}\\
            &\quad=\sum_{\tau'\in\mathcal{R}_{\mathbf{d}}(m)}\Bigl(\sum_{\substack{Y\in\mathcal{Q}\\\Phi(Y)=\tau'}}\widehat{\mathbf{P}}^{\,r}(X,Y)\Bigr)\log\frac{\displaystyle\sum_{\substack{Y\in\mathcal{Q}\\\Phi(Y)=\tau'}}\widehat{\mathbf{P}}^{\,r}(X,Y)}{\displaystyle\sum_{\substack{Y\in\mathcal{Q}\\\Phi(Y)=\tau'}}{\pi_{\mathcal{Q}}}(Y)}\\
            &\quad\le\sum_{\tau'\in\mathcal{R}_{\mathbf{d}}(m)}\sum_{\substack{Y\in\mathcal{Q}\\\Phi(Y)=\tau'}}\widehat{\mathbf{P}}^{\,r}(X,Y)\log\frac{\widehat{\mathbf{P}}^{\,r}(X,Y)}{\pi_{\mathcal{Q}}(Y)}\\
            &\quad=\sum_{Y\in\mathcal{Q}}\widehat{\mathbf{P}}^{\,r}(X,Y)\log\frac{\widehat{\mathbf{P}}^{\,r}(X,Y)}{\pi_{\mathcal{Q}}(Y)}\\
            &\quad=\sum_{Y\in\mathcal{Q}}\widehat{\mathbf{P}}^{\,r}(X,Y)\log\frac{\widehat{\mathbf{P}}^{\,r}(X,Y)}{\pi_{\mathcal{P}}(Y)}+\log\frac{|\mathcal{Q}|}{|\mathcal{P}|}\\
            &\quad\le D(\widehat{\mathbf{P}}^{\,r}(X,\cdot)\,\Vert\,\pi_{\mathcal{P}}).
        \end{align*}
    Next, define the kernel $\mathbf{K}$ on $\mathcal{P}$ by uniformly choosing two distinct pairs and resampling the pairing of their four stubs. Each of the three possible pairings is chosen with probability $1/3$, and all other pairs remain unchanged. Extend $\widehat{\mathbf{P}}$ to a Markov kernel on $\mathcal{P}$ by setting $\widehat{\mathbf{P}}(Z,\cdot)=\mathbf{K}(Z,\cdot)$ for $Z\notin\mathcal{Q}$. This leaves its laws started in $\mathcal{Q}$ unchanged. Every transition with positive probability under $\widehat{\mathbf{P}}$ also has positive probability under $\mathbf{K}$, and the same holds for their powers. Hence~\cref{lem:weak-triangle-inequality} gives
        \begin{align}\label{eq:relative-entropy-weak-triangle}
            D(\widehat{\mathbf{P}}^{\,r}(X,\cdot)\,\Vert\,\pi_{\mathcal{P}}) &\le2D(\widehat{\mathbf{P}}^{\,r}(X,\cdot)\,\Vert\,\mathbf{K}^{r}(X,\cdot))\notag\\
            &\qquad+\log\Bigl(1+\Bigl\|\frac{\mathbf{K}^{r}(X,\cdot)}{\pi_{\mathcal{P}}}-\mathbf{1}\Bigr\|_{\pi_{\mathcal{P}}}^{2}\Bigr).
        \end{align}
    We bound the two terms on the right-hand side separately.

    For the first term in~\cref{eq:relative-entropy-weak-triangle}, recall from the proof of~\cref{lem:invalid-transpositions}, with $\sigma=\varnothing$ and $k=m$, that the number of invalid transpositions from $X$ is at most $8m\Delta^{2}$. Each nonidentity replacement of two pairs is obtained by exactly two transpositions: for example, replacing $\{\vec{v},\vec{z}\},\{\vec{u},\vec{w}\}$ by $\{\vec{u},\vec{z}\},\{\vec{v},\vec{w}\}$ is obtained by $\theta_{\vec{v},\vec{u}}$ or $\theta_{\vec{z},\vec{w}}$. Each such replacement has probability $1/(3\binom{m}{2})$ under $\mathbf{K}$, so
        \begin{align}\label{eq:invalid-transitions-bound}
            \sum_{Y\in\mathcal{P}\setminus\mathcal{Q}}\mathbf{K}(X,Y) &\le\frac{8m\Delta^{2}}{2}\frac{1}{3\binom{m}{2}}=\frac{8\Delta^{2}}{3(m-1)}\le\frac{8\Delta^{2}}{m}.
        \end{align}
    Conditional on selecting $W\in\binom{X}{2}$ for replacement, each of the three pairings of its four stubs is chosen with probability $1/3$ under $\mathbf{K}$, and each valid completion is selected with probability $1/g_{X}(W)$ under $\widehat{\mathbf{P}}$. Applying the log-sum inequality when grouping choices $(W,W')$ that give the same pairing yields
        \begin{align*}
            &D(\widehat{\mathbf{P}}(X,\cdot)\,\Vert\,\mathbf{K}(X,\cdot))\\
            &\quad=\sum_{Y\in\mathcal{Q}}\widehat{\mathbf{P}}(X,Y)\log\frac{\widehat{\mathbf{P}}(X,Y)}{\mathbf{K}(X,Y)}\\
            &\quad=\sum_{Y\in\mathcal{Q}} \Bigl(\sum_{\substack{(W,W')\\(X\setminus W)\cup W'=Y}}\frac{1}{\binom{m}{2}\,g_{X}(W)}\Bigr) \log\frac{\displaystyle\sum_{\substack{(W,W')\\(X\setminus W)\cup W'=Y}}\frac{1}{\binom{m}{2}\,g_{X}(W)}}{\displaystyle\sum_{\substack{(W,W')\\(X\setminus W)\cup W'=Y}}\frac{1}{3\binom{m}{2}}}\\
            &\quad\le \frac{1}{\binom{m}{2}}\sum_{W\in\binom{X}{2}}\sum_{\substack{W'\in\mathcal{M}(W)\\(X\setminus W)\cup W'\in\mathcal{Q}}} \frac{1}{g_{X}(W)}\log\frac{3}{g_{X}(W)}\\
            &\quad=\frac{1}{\binom{m}{2}}\sum_{W\in\binom{X}{2}}\log\frac{3}{g_{X}(W)}.
        \end{align*}
    Using $\log(3/u)\le3-u$ for $1\le u\le3$, followed by the bound in~\cref{eq:invalid-transitions-bound}, we obtain
        \begin{align}\label{eq:heatbath-local-kl}
            D(\widehat{\mathbf{P}}(X,\cdot)\,\Vert\,\mathbf{K}(X,\cdot)) &\le\frac{1}{\binom{m}{2}}\sum_{W\in\binom{X}{2}}(3-g_{X}(W)) =3\sum_{Y\in\mathcal{P}\setminus\mathcal{Q}}\mathbf{K}(X,Y)\le\frac{24\Delta^{2}}{m}.
        \end{align}
    By~\cref{lem:entropy-chain-rule}, for every integer $s\ge1$,
        \begin{align*}
            D(\widehat{\mathbf{P}}^{\,s}(X,\cdot)\,\Vert\,\mathbf{K}^{s}(X,\cdot)) &\le D(\widehat{\mathbf{P}}^{\,s-1}(X,\cdot)\,\Vert\,\mathbf{K}^{s-1}(X,\cdot))+\frac{24\Delta^{2}}{m},
        \end{align*}
    where we use~\cref{eq:heatbath-local-kl}. Applying this inequality repeatedly gives
        \begin{align}\label{eq:pairing-path-kl}
            D(\widehat{\mathbf{P}}^{\,r}(X,\cdot)\,\Vert\,\mathbf{K}^{r}(X,\cdot)) &\le r\frac{24\Delta^{2}}{m},
        \end{align}
    since both initial distributions assign mass one to $X$.

    For the second term in~\cref{eq:relative-entropy-weak-triangle}, fix a labelling of the set $\mathcal{S}$ of all $2m$ stubs, and let $\widetilde{\mathcal{P}}$ denote the set of orderings of $\mathcal{S}$. Define the map $\Psi:\widetilde{\mathcal{P}}\to\mathcal{P}$ according to
        \begin{align*}
            (\vec{v}_{1},\dotsc,\vec{v}_{2m}) &\mapsto\{\{\vec{v}_{1},\vec{v}_{2}\},\dotsc,\{\vec{v}_{2m-1},\vec{v}_{2m}\}\}
        \end{align*}
    for each $(\vec{v}_{1},\dotsc,\vec{v}_{2m})\in\widetilde{\mathcal{P}}$. $\Psi$ identifies each ordering of the stubs with a pairing of the stubs by forgetting the order of the pairs and the order of the stubs within each pair. Each fiber $\Psi^{-1}(Z)$ of this map contains $(m!)2^{m}$ ordered presentations of $Z$, independent of $Z\in\mathcal{P}$. Set $p=\frac{2m-1}{3(m-1)}\in[2/3,1]$. Then $\frac{2p}{\binom{2m}{2}}=\frac{1}{3\binom{m}{2}}$, which is the probability assigned by $\mathbf{K}$ to each nontrivial transition. Define the kernel $\widetilde{\mathbf{K}}$ on $\widetilde{\mathcal{P}}$ by staying at the current ordering with probability $1-p$, and otherwise exchanging two uniformly chosen distinct entries.

    Fix an ordering $\widetilde{X}=(\vec{v}_{1},\dotsc,\vec{v}_{2m})$ with $\Psi(\widetilde{X})=X$, and let $t\ge3m\log(2m)$. For each ordering $\widetilde{Y}\in\widetilde{\mathcal{P}}$, let $\varphi_{\widetilde{Y}}\in\mathfrak{S}_{2m}$ be the unique permutation satisfying
        \begin{align*}
            \widetilde{Y} &=(\vec{v}_{\varphi_{\widetilde{Y}}(1)},\dotsc,\vec{v}_{\varphi_{\widetilde{Y}}(2m)}).
        \end{align*}
    This gives a bijection between $\widetilde{\mathcal{P}}$ and $\mathfrak{S}_{2m}$ under which the initial ordering $\widetilde{X}$ corresponds to the identity permutation $\iota$.

    Let $\mathbf{Q}$ denote the random transposition kernel from~\cref{thm:random-transposition-l2}, with $N=2m$. Under the identification $\widetilde{Y}\mapsto\varphi_{\widetilde{Y}}$, exchanging entries $i$ and $j$ of an ordering corresponds to replacing $\varphi_{\widetilde{Y}}$ by $\varphi_{\widetilde{Y}}\circ(i\,j)$. Choosing the two entries uniformly therefore gives one step of $\mathbf{Q}$. Thus, after identifying the rows and columns by this bijection, $\widetilde{\mathbf{K}}=(1-p)\mathbf{I}+p\mathbf{Q}$. Since $\varphi_{\widetilde{X}}=\iota$, it follows that for each $\widetilde{Y}\in\widetilde{\mathcal{P}}$,
        \begin{align*}
            e^{t(\widetilde{\mathbf{K}}-\mathbf{I})}(\widetilde{X},\widetilde{Y}) &=e^{t((1-p)\mathbf{I}+p\mathbf{Q}-\mathbf{I})}(\iota,\varphi_{\widetilde{Y}}) =e^{pt(\mathbf{Q}-\mathbf{I})}(\iota,\varphi_{\widetilde{Y}}) =\mu_{pt}(\varphi_{\widetilde{Y}}),
        \end{align*}
    where in the last equality we recall the definition of $\mu_{t}$ in~\cref{thm:random-transposition-l2}. Since $p\ge2/3$ and $t\ge3m\log(2m)$, we have $pt\ge2m\log(2m)$. Thus, by~\cref{thm:random-transposition-l2},
        \begin{align*}
            \Bigl\|\frac{e^{t(\widetilde{\mathbf{K}}-\mathbf{I})}(\widetilde{X},\cdot)}{\pi_{\mathfrak{S}}}-\mathbf{1}\Bigr\|_{\pi_{\mathfrak{S}}}^{2} &\le1.
        \end{align*}

    We now apply this estimate to the walk $\mathbf{K}$ on $\mathcal{P}$. For every $\widetilde{Z}\in\widetilde{\mathcal{P}}$ and $Y\in\mathcal{P}$, we claim that
        \begin{align}\label{eq:pairing-projection}
            \sum_{\substack{\widetilde{Y}\in\widetilde{\mathcal{P}}\\\Psi(\widetilde{Y})=Y}}\widetilde{\mathbf{K}}(\widetilde{Z},\widetilde{Y}) &=\mathbf{K}(\Psi(\widetilde{Z}),Y).
        \end{align}
    Fix $\widetilde{Z}$ and write $Z=\Psi(\widetilde{Z})$. Suppose first that $Y\ne Z$ is obtained by replacing two pairs of $Z$. The two exchanges producing this replacement give two distinct orderings representing $Y$, each reached with probability $p/\binom{2m}{2}$. Thus, using $p=(2m-1)/(3(m-1))$, we have
        \begin{align*}
            \sum_{\substack{\widetilde{Y}\in\widetilde{\mathcal{P}}\\\Psi(\widetilde{Y})=Y}}\widetilde{\mathbf{K}}(\widetilde{Z},\widetilde{Y}) &=\frac{p}{\binom{2m}{2}}+\frac{p}{\binom{2m}{2}} =\frac{1}{3\binom{m}{2}}=\mathbf{K}(Z,Y).
        \end{align*}
    For $Y=Z$, the sum includes the original ordering, reached with probability $1-p$, and the $m$ orderings obtained by exchanging the two stubs within one pair, each reached with probability $p/\binom{2m}{2}$. Therefore
        \begin{align*}
            \sum_{\substack{\widetilde{Y}\in\widetilde{\mathcal{P}}\\\Psi(\widetilde{Y})=Z}}\widetilde{\mathbf{K}}(\widetilde{Z},\widetilde{Y}) &=1-p+\frac{pm}{\binom{2m}{2}} =\frac{1}{3}=\mathbf{K}(Z,Z).
        \end{align*}
    If $Y\ne Z$ cannot be obtained by replacing two pairs, both sides of the claimed identity are zero. For $X$ and its ordering $\widetilde{X}$ fixed earlier, the same induction as in~\cref{eq:pairing-projection-recursion} gives, for every integer $s\ge0$,
        \begin{align*}
            \mathbf{K}^{s}(X,Y) &=\sum_{\substack{\widetilde{Y}\in\widetilde{\mathcal{P}}\\\Psi(\widetilde{Y})=Y}}\widetilde{\mathbf{K}}^{\,s}(\widetilde{X},\widetilde{Y}).
        \end{align*}
    Therefore it follows from~\cref{eq:pairing-projection} that
        \begin{align*}
            e^{t(\mathbf{K}-\mathbf{I})}(X,Y) &=e^{-t}\sum_{s=0}^{\infty}\frac{t^{s}}{s!}\mathbf{K}^{s}(X,Y) =e^{-t}\sum_{s=0}^{\infty}\frac{t^{s}}{s!}\sum_{\substack{\widetilde{Y}\in\widetilde{\mathcal{P}}\\\Psi(\widetilde{Y})=Y}}\widetilde{\mathbf{K}}^{\,s}(\widetilde{X},\widetilde{Y}) =\sum_{\substack{\widetilde{Y}\in\widetilde{\mathcal{P}}\\\Psi(\widetilde{Y})=Y}}e^{t(\widetilde{\mathbf{K}}-\mathbf{I})}(\widetilde{X},\widetilde{Y}).
        \end{align*}
    Since each pairing has $2^{m} m!$ ordered presentations, we have
        \begin{align*}
            |\widetilde{\mathcal{P}}| &=(2m)!=2^{m} m!\,|\mathcal{P}|,
        \end{align*}
    and, for each $\widetilde{Y}\in\widetilde{\mathcal{P}}$ with $\Psi(\widetilde{Y})=Y$, we have
        \begin{align*}
            \frac{\pi_{\mathcal{P}}(Y)}{2^{m} m!}&=\frac{1}{(2m)!}=\pi_{\mathfrak{S}}(\widetilde{Y}).
        \end{align*}
    Dividing the preceding transition identity by $\pi_{\mathcal{P}}(Y)$ therefore gives
        \begin{align*}
            \frac{e^{t(\mathbf{K}-\mathbf{I})}(X,Y)}{\pi_{\mathcal{P}}(Y)}-1 &=\frac{1}{2^{m} m!}\sum_{\substack{\widetilde{Y}\in\widetilde{\mathcal{P}}\\\Psi(\widetilde{Y})=Y}}\Bigl(\frac{e^{t(\widetilde{\mathbf{K}}-\mathbf{I})}(\widetilde{X},\widetilde{Y})}{\pi_{\mathfrak{S}}(\widetilde{Y})}-1\Bigr).
        \end{align*}
    Applying Jensen's inequality to the preceding average, we obtain
        \begin{align*}
            \Bigl\|\frac{e^{t(\mathbf{K}-\mathbf{I})}(X,\cdot)}{\pi_{\mathcal{P}}}-\mathbf{1}\Bigr\|_{\pi_{\mathcal{P}}}^{2} &\le\sum_{Y\in\mathcal{P}}\frac{\pi_{\mathcal{P}}(Y)}{2^{m} m!}\sum_{\substack{\widetilde{Y}\in\widetilde{\mathcal{P}}\\\Psi(\widetilde{Y})=Y}}\Bigl(\frac{e^{t(\widetilde{\mathbf{K}}-\mathbf{I})}(\widetilde{X},\widetilde{Y})}{\pi_{\mathfrak{S}}(\widetilde{Y})}-1\Bigr)^{2}\\
            &=\sum_{\widetilde{Y}\in\widetilde{\mathcal{P}}}{\pi_{\mathfrak{S}}}(\widetilde{Y})\Bigl(\frac{e^{t(\widetilde{\mathbf{K}}-\mathbf{I})}(\widetilde{X},\widetilde{Y})}{\pi_{\mathfrak{S}}(\widetilde{Y})}-1\Bigr)^{2}\\
            &=\Bigl\|\frac{e^{t(\widetilde{\mathbf{K}}-\mathbf{I})}(\widetilde{X},\cdot)}{\pi_{\mathfrak{S}}}-\mathbf{1}\Bigr\|_{\pi_{\mathfrak{S}}}^{2}\le1,
        \end{align*}
    using the choice $t\ge3m\log(2m)$. Here, the first equality uses $\pi_{\mathcal{P}}(Y)/(2^{m} m!)=\pi_{\mathfrak{S}}(\widetilde{Y})$ and the fact that each ordering projects to exactly one pairing.

    It remains to pass from continuous time back to discrete time. The kernel $\mathbf{K}$ is symmetric, since each nonidentity transition has probability $1/(3\binom{m}{2})$. For $f\in\ell^{2}(\mathcal{P},\pi_{\mathcal{P}})$, let $W$ range over partial pairings with $m-2$ pairs. Each $W$ has three completions, and each pairing contains $\binom{m}{2}$ such $W$. Therefore
        \begin{align*}
            \langle f,\mathbf{K}f\rangle_{\pi_{\mathcal{P}}} &=\frac{1}{3|\mathcal{P}|\binom{m}{2}}\sum_{W}\sum_{\substack{Y,Z\in\mathcal{P}\\W\subseteq Y\cap Z}}f(Y)f(Z) = \frac{1}{3|\mathcal{P}|\binom{m}{2}}\sum_{W}\Bigl(\sum_{\substack{Y\in\mathcal{P}\\W\subseteq Y}}f(Y)\Bigr)^{2}\ge0.
        \end{align*}
    Thus $\mathbf{K}$ has eigenvalues in $[0,1]$. Let $\phi_{1},\dotsc,\phi_{|\mathcal{P}|}$ be an orthonormal basis of right eigenfunctions in $\ell^{2}(\mathcal{P},\pi_{\mathcal{P}})$, with $\phi_{1}=\mathbf{1}$ and corresponding eigenvalues $\lambda_{j}(\mathbf{K})$. For every integer $r\ge3m\log(2m)$, using $x^{2r}\le e^{-2r(1-x)}$ for $0\le x\le 1$ and evaluating the preceding heat-kernel bound at $t=r$, we have
        \begin{align*}
            \Bigl\|\frac{\mathbf{K}^{r}(X,\cdot)}{\pi_{\mathcal{P}}}-\mathbf{1}\Bigr\|_{\pi_{\mathcal{P}}}^{2} &=\sum_{j=2}^{|\mathcal{P}|}\lambda_{j}(\mathbf{K})^{2r}\phi_{j}(X)^{2}\\
            &\le\sum_{j=2}^{|\mathcal{P}|}e^{-2r(1-\lambda_{j}(\mathbf{K}))}\phi_{j}(X)^{2}\\
            &=\Bigl\|\frac{e^{r(\mathbf{K}-\mathbf{I})}(X,\cdot)}{\pi_{\mathcal{P}}}-\mathbf{1}\Bigr\|_{\pi_{\mathcal{P}}}^{2}\le1.
        \end{align*}
    Thus the second term in~\cref{eq:relative-entropy-weak-triangle} satisfies
        \begin{align*}
            \log\Bigl(1+\Bigl\|\frac{\mathbf{K}^{r}(X,\cdot)}{\pi_{\mathcal{P}}}-\mathbf{1}\Bigr\|_{\pi_{\mathcal{P}}}^{2}\Bigr) &\le\log2\le1.
        \end{align*}
    Combining this with~\cref{eq:relative-entropy-weak-triangle,eq:pairing-path-kl} and the entropy projection estimate at the start of the proof gives
        \begin{align*}
            D(\mathbf{P}_{2}^{r}(\Phi(X),\cdot)\,\Vert\,\pi_{m}) &\le2r\frac{24\Delta^{2}}{m}+1.
        \end{align*}
    The preceding upper bound increases with $r$, so we first bound it on a finite interval and then use entropy monotonicity to cover all later times. For every integer $3m\log(2m)\le r\le4m\log(2m)$, we have
        \begin{align*}
            2r\frac{24\Delta^{2}}{m}+1 &\le192\Delta^{2}\log(2m)+1\le193\Delta^{2}\log(2m).
        \end{align*}
    This interval contains $r_{0}=\lceil3m\log(2m)\rceil$, since $m\ge2$. Finally, stationarity of $\pi_{m}$ and~\cref{lem:entropy-chain-rule}, applied with both kernels equal to $\mathbf{P}_{2}$, give
        \begin{align*}
            D(\mathbf{P}_{2}^{s+1}(\tau,\cdot)\,\Vert\,\pi_{m}) &\le D(\mathbf{P}_{2}^{s}(\tau,\cdot)\,\Vert\,\pi_{m})
        \end{align*}
    for every realization $\tau$ and integer $s\ge0$. Thus the bound at $r_{0}$ holds at every later integer time. Since $X\in\mathcal{Q}$ was arbitrary and every realization has a preimage under $\Phi$, this proves~\cref{prop:two-edge-entropy-bound}.

The walk $\mathbf{P}_{2}$ is reversible with respect to $\pi_{m}$ and has nonnegative eigenvalues by~\cref{prop:up-down-adjoint}. For sufficiently large $C$, our hypothesis and~\cref{thm:two-edge-eigenvalue} give a positive spectral gap, so the walk is irreducible.

    Choose an integer $r$ satisfying $3m\log(2m)\le r\le4m\log(2m)$. Applying~\cref{lem:salez-entropy-gap} with the entropy bound from~\cref{prop:two-edge-entropy-bound}, we obtain
        \begin{align*}
            t_{\mathrm{mix}}(\mathbf{P}_{2},1/4) &\le r+\frac{4(193\Delta^{2}\log(2m)+1)}{1-\lambda_{2}(\mathbf{P}_{2})}\\
            &\le\Bigl(4m+\frac{780\Delta^{2}}{1-\lambda_{2}(\mathbf{P}_{2})}\Bigr)\log(2m),
        \end{align*}
    where we use $r\le4m\log(2m)$, $\Delta\ge1$ and $\log(2m)\ge\log2$.

    If $m\ge C\Delta^{8}$ for a sufficiently large absolute constant $C$, then~\cref{thm:two-edge-eigenvalue} gives $1-\lambda_{2}(\mathbf{P}_{2})\ge1/(C'm)$ for an absolute constant $C'>0$. Substituting into the preceding bound yields
        \begin{align*}
            t_{\mathrm{mix}}(\mathbf{P}_{2},1/4) &\le(4+780C'\Delta^{2})m\log(2m)\le C\Delta^{2}m\log(2m),
        \end{align*}
    after increasing $C$ if necessary. The theorem is proved.

\label{prop:classical-simplicial-comparison}
    Let $f\in\ell^{2}(\mathcal{R}_{\mathbf{d}}(m),\pi_{m})$ be arbitrary. Then
        \begin{align}\label{eq:classical-simplicial-energy}
            \frac{b}{3a}\mathcal{E}_{\mathbf{P}_{2}}(f,f) &\le \mathcal{E}_{\mathbf{S}}(f,f) \le \frac{b}{2a}\mathcal{E}_{\mathbf{P}_{2}}(f,f).
        \end{align}
    Consequently,
        \begin{align}\label{eq:classical-simplicial-eigenvalue}
            \frac{b}{3a}(1-\lambda_{2}(\mathbf{P}_{2})) &\le 1-\lambda_{2}(\mathbf{S}) \le \frac{b}{2a}(1-\lambda_{2}(\mathbf{P}_{2})).
        \end{align}

Fix distinct realizations $\tau,\tau'$ related by a switch, and let $\sigma=\tau\cap \tau'$. The two deleted edges are determined by $\tau,\tau'$, and $\sigma$ has $g(\sigma)\in\{2,3\}$ valid completions. Thus
        \begin{align*}
            \mathbf{P}_{2}(\tau,\tau')&=\frac{1}{b\,g(\sigma)}\;,                                                              
        \end{align*}
    and similarly,
        \begin{align*}
            \frac{\mathbf{S}(\tau,\tau')}{\mathbf{P}_{2}(\tau,\tau')}&=\frac{b\,g(\sigma)}{6a}.
        \end{align*}
    If the two edges selected by $\mathbf{P}_{2}$ share a vertex, their residual degrees determine their completion uniquely, resulting in a holding step. Using the preceding two identities to bound the transition probabilities in the Dirichlet forms of $\mathbf{P}_{2}$ and $\mathbf{S}$ proves~\cref{eq:classical-simplicial-energy}. Taking the infimum over functions of positive variance proves~\cref{eq:classical-simplicial-eigenvalue}.

\label{cor:classical-switch-eigenvalue}
    There exists an absolute constant $C>0$ with the following property. If $m\ge C\Delta^{8}$, then
        \begin{align*}
            1-\frac{2}{m} &\le\lambda_{2}(\mathbf{S})\le1-\frac{1}{Cm}.
        \end{align*}

\label{cor:classical-switch-mixing}
    There exists an absolute constant $C>0$ with the following property. If $m\ge C\Delta^{8}$, then
        \begin{align}\label{eq:classical-switch-mixing-quantitative}
            t_{\mathrm{mix}}(\mathbf{S},1/4) &\le C\Delta^{2}m\log(m).
        \end{align}
